import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    counted = df[df['row_kind'] == 'counted'].copy()

    counted['Service From'] = pd.to_datetime(counted['Service From'], errors='coerce')
    counted['Paid Date'] = pd.to_datetime(counted['Paid Date'], errors='coerce')

    cpt_paid = (
        counted.groupby('CPT/HCPCS')['Paid Amount']
        .sum()
        .reset_index()
        .sort_values('Paid Amount', ascending=False)
        .head(10)
    )

    result['segments'].append({
        "segment_column": "CPT/HCPCS",
        "metric_column": "Paid Amount",
        "aggregation": "sum",
        "label": "top_procedures_by_paid",
        "results": [
            {"name": str(row['CPT/HCPCS']), "value": float(row['Paid Amount'])}
            for _, row in cpt_paid.iterrows()
        ]
    })
except Exception as e:
    result['segments'].append({
        "segment_column": "CPT/HCPCS",
        "metric_column": "Paid Amount",
        "aggregation": "sum",
        "label": "top_procedures_by_paid",
        "results": []
    })

try:
    cpt_count = (
        counted.groupby('CPT/HCPCS')['Claim ID']
        .nunique()
        .reset_index()
        .rename(columns={'Claim ID': 'claim_count'})
        .sort_values('claim_count', ascending=False)
        .head(10)
    )

    result['segments'].append({
        "segment_column": "CPT/HCPCS",
        "metric_column": "Claim ID",
        "aggregation": "count",
        "label": "top_procedures_by_claim_count",
        "results": [
            {"name": str(row['CPT/HCPCS']), "value": float(row['claim_count'])}
            for _, row in cpt_count.iterrows()
        ]
    })
except Exception:
    pass

try:
    cpt_avg = (
        counted.groupby('CPT/HCPCS')['Paid Amount']
        .mean()
        .reset_index()
        .sort_values('Paid Amount', ascending=False)
        .head(10)
    )

    result['segments'].append({
        "segment_column": "CPT/HCPCS",
        "metric_column": "Paid Amount",
        "aggregation": "mean",
        "label": "top_procedures_by_avg_paid",
        "results": [
            {"name": str(row['CPT/HCPCS']), "value": float(row['Paid Amount'])}
            for _, row in cpt_avg.iterrows()
        ]
    })
except Exception:
    pass

result['assumptions'].append("Only 'counted' rows used; voided, superseded, and test rows excluded.")
result['assumptions'].append("Paid Amount summed at line level; Claim Total Billed not used to avoid double-counting.")
result['assumptions'].append("Top 10 CPT/HCPCS codes ranked by total Paid Amount.")
result['assumptions'].append("Claim counts use distinct Claim IDs per CPT/HCPCS code.")

